    TAPER_PARAMETERSVectorOffset TAPER_PARAMETERS: Offset = Offset(),
    STEERING_AZIMUTH_DEG: Double = 0.0,
    STEERING_ELEVATION_DEG: Double = 0.0,
    STEERING_CONE_DEG: Double = 0.0,
    STEERING_CLOCK_DEG: Double = 0.0,
